-- Comprobación de las traducciones de ticket activas.
SELECT COUNT(*) AS TICKETS_CA_ES
  FROM fza_traducciones
 WHERE IDIOMA_TRAD = 'ca-ES'
   AND ESACTIVO_TRAD = 'S'
   AND CLAVE_TRAD LIKE 'inLibMsgTickets.%';
